const app=document.querySelector('#app');let timer=null;let position=0;let currentTheme='minimal';
const designs={minimal:{label:'01 / MINIMAL'},field:{label:'02 / FIELD MANUAL'},signal:{label:'03 / SIGNAL'}};
function terrain(units=true){return `<svg viewBox="0 0 600 440" role="img" aria-label="Illustrative tactical terrain map"><defs><pattern id="grid" width="40" height="40" patternUnits="userSpaceOnUse"><path d="M40 0H0V40" fill="none" stroke="currentColor" opacity=".10"/></pattern></defs><rect width="600" height="440" fill="url(#grid)"/><g fill="none" stroke="currentColor" opacity=".18">${Array.from({length:8},(_,i)=>`<path d="M${-120+i*24} 440 Q${70+i*25} 300 ${10+i*28} 170 T${280+i*25} -40"/>`).join('')}<path d="M0 320Q180 240 230 290T600 200" stroke-width="25" opacity=".35"/><path d="M0 320Q180 240 230 290T600 200" stroke-width="2"/></g><g fill="currentColor" opacity=".13"><rect x="345" y="130" width="32" height="45" transform="rotate(20 345 130)"/><rect x="395" y="156" width="45" height="24"/><rect x="370" y="205" width="28" height="20"/></g><g id="routeLayer"><path d="M100 355L210 305L290 230L410 150" stroke="var(--accent)" stroke-width="2" stroke-dasharray="7 7" fill="none"/><circle cx="410" cy="150" r="40" fill="none" stroke="var(--accent)"/><path d="M410 135v30m-15-15h30" stroke="var(--accent)"/></g>${units?'<g id="unitLayer"><g id="squad" transform="translate(210 305)"><circle r="20" fill="var(--accent)" opacity=".15"/><circle r="6" fill="var(--accent)"/><text x="17" y="-13" font-size="11" fill="var(--ink)" font-family="monospace">ALPHA</text></g><g transform="translate(270 330)"><path d="M0-6L7 6H-7Z" fill="var(--accent)"/><text x="14" y="5" font-size="10" fill="var(--ink)" font-family="monospace">BRAVO</text></g></g>':''}</svg>`}
function link(page,text,cls=''){return `<a class="${cls}" href="#${currentTheme}/${page}">${text}</a>`}

function navigation(page){
 const links=currentTheme==='minimal'?[['home','Overview'],['operations','Sessions'],['playback','Briefing player'],['join','Get started']]:currentTheme==='field'?[['home','01 / Headquarters'],['operations','02 / Deployment'],['playback','03 / After action'],['join','04 / Enlist']]:[['home','Discover'],['operations','Rendezvous'],['playback','Rewind'],['join','Connect']];
 return `<nav aria-label="Main navigation">${links.map(([route,label])=>`<a href="#${currentTheme}/${route}" ${page===route?'aria-current="page"':''}>${label}</a>`).join('')}</nav>`;
}
function shell(page,content){
 const source='<a href="https://globalconflicts.net/" target="_blank" rel="noopener">Community site ↗</a>';
 if(currentTheme==='minimal')return `<div class="minimal-shell"><header class="utility-rail">${link('home','<span class="wordmark">gc<span>.</span></span><span>Global Conflicts</span>','utility-brand')}<div class="rail-label">COMMUNITY</div>${navigation(page)}<div class="rail-bottom"><span class="status-dot"></span> Arma Reforger<br>${source}</div></header><main><div class="utility-top"><span>Global Conflicts / ${page==='home'?'Overview':page==='playback'?'Briefing player':page==='operations'?'Sessions':'Get started'}</span><span>Community prototype</span></div>${content}<footer>Good people. Shared objectives.<span>${source}</span></footer></main></div>`;
 if(currentTheme==='field')return `<div class="field-shell"><header class="command-header">${link('home','<span class="insignia">G<span>✦</span>C</span><span>GLOBAL<br>CONFLICTS</span>','command-brand')}<span class="command-meta">ARMA REFORGER COMMUNITY<br>TEAMWORK ABOVE ALL</span><a href="#field/join" class="field-join">REPORT FOR DUTY ↗</a></header><div class="command-tabs">${navigation(page)}<span>GC / FIELD MANUAL</span></div><main>${content}</main><footer><span>GLOBAL CONFLICTS / FIELD MANUAL</span><span>Imagery from the <a href="https://globalconflicts.net/" target="_blank" rel="noopener">GC community site ↗</a> · concept</span></footer></div>`;
 return `<div class="signal-shell"><header class="signal-header">${link('home','<span class="signal-glyph">✳</span><span>GLOBAL<br>CONFLICTS</span>','signal-brand')}<span class="signal-frequency">COMMUNITY FREQUENCY<br>ARMA REFORGER</span><span class="signal-index">GC—003</span></header><main>${content}</main><div class="signal-dock">${navigation(page)}<a class="dock-source" href="https://globalconflicts.net/" target="_blank" rel="noopener" aria-label="Original Global Conflicts site">↗</a></div><footer><span>Signal / an experimental community interface</span><span>Design concept · ${source}</span></footer></div>`;
}
function render(){window.scrollTo(0,0);clearInterval(timer);timer=null;const parts=location.hash.slice(1).split('/');currentTheme=designs[parts[0]]?parts[0]:'minimal';const page=['home','operations','playback','join'].includes(parts[1])?parts[1]:'home';document.body.className=currentTheme+' page-'+page;document.querySelectorAll('[data-theme]').forEach(a=>{a.classList.toggle('active',a.dataset.theme===currentTheme);a.href='#'+a.dataset.theme+'/'+page});app.innerHTML=shell(page,page==='home'?home():page==='playback'?playback():page==='operations'?operations():join());if(page==='playback')wirePlayer();if(currentTheme==='signal'&&page==='home')wireSignal();document.title=`${designs[currentTheme].label.slice(5)} — Global Conflicts`;}
function home(){
 if(currentTheme==='minimal')return `<section class="simple-intro"><span class="plain-label">A place to play together.</span><h1>Tactical gameplay.<br>Without the ceremony.</h1><p>We’re Global Conflicts, an Arma Reforger community.<br>Good teamwork. Community-made missions. No e-salutes.</p>${link('join','Join the community <span>↗</span>','btn')}</section><section class="simple-schedule"><div><span class="plain-label">The weekend plan</span><h2>Saturday & Sunday</h2><p>Reference schedule. Confirm Reforger events with GC.</p></div><div class="simple-time">19:00<span>UTC</span></div>${link('operations','Session details →','text-link')}</section><section class="simple-directory"><a href="#minimal/join"><span class="directory-icon">↗</span><div><h3>New here?</h3><p>Microphone on. Meet the community. Find your squad.</p></div><span>Get started →</span></a><a href="#minimal/playback"><span class="directory-icon">▷</span><div><h3>Review a briefing</h3><p>A simple workspace for the bigger picture.</p></div><span>Try the demo →</span></a></section>`;
 if(currentTheme==='field')return `<section class="dossier"><div class="dossier-copy"><div class="document-meta"><span>COMMUNITY DOSSIER</span><span>NO. GC—001</span></div><div class="dossier-title"><span class="stamp">OPEN TO ALL</span><h1>BE PART<br>OF THE<br><em>OPERATION.</em></h1></div><div class="dossier-description"><span>01 / MISSION</span><p>Serious teamwork.<br>No rank required.</p></div><div class="dossier-action">${link('join','JOIN THE COMMUNITY <span>↗</span>','btn')}<span>ARMA REFORGER<br>GLOBAL CONFLICTS</span></div></div><div class="field-board"><div class="board-grid"></div><div class="board-cross cross-one">+</div><div class="board-cross cross-two">+</div><div class="field-photo"><img src="community.jpg" alt="Vehicles on a forest road from the Global Conflicts community archive"><span>GC ARCHIVE / FIELD CONDITIONS</span></div><div class="deployment-slip"><span class="slip-tab">WEEKEND OPERATIONS</span><div class="slip-body"><span class="small-mono">02 / RENDEZVOUS</span><h2>SAT + SUN</h2><div class="slip-time">1900<span>UTC</span></div><p>Reference schedule.<br>Confirm Reforger events with GC.</p>${link('operations','VIEW SESSION DETAILS ↗')}</div></div><span class="map-footnote">REFERENCE MAP / COMMUNITY ARCHIVE</span></div></section><section class="field-bottom"><div><span class="small-mono">03 / EQUIPMENT CHECK</span><p>A working mic.<br>A mature attitude.</p>${link('join','READ JOINING INSTRUCTIONS →','text-link')}</div><a class="after-action" href="#field/playback"><div><span class="small-mono">04 / AFTER ACTION</span><h2>EVERY OPERATION<br>HAS A STORY.</h2><span>OPEN BRIEFING PLAYBACK DEMO →</span></div><span class="field-play">▷</span></a></section>`;
 return `<section class="transmission"><div class="signal-topline"><span>A SHARED WORLD. A SHARED OBJECTIVE.</span><span>INTERACTIVE TRANSMISSION / 003</span></div><h1>NO ONE<br><span>PLAYS ALONE.</span></h1><div class="signal-world">${globe()}<div class="world-axis axis-a"></div><div class="world-axis axis-b"></div><button class="beacon beacon-one selected" data-channel="who" aria-label="Who we are" aria-pressed="true"><span></span>01 / WHO</button><button class="beacon beacon-two" data-channel="when" aria-label="When we play" aria-pressed="false"><span></span>02 / WHEN</button><button class="beacon beacon-three" data-channel="how" aria-label="How to join" aria-pressed="false"><span></span>03 / HOW</button><span class="world-caption">SELECT A SIGNAL TO EXPLORE</span></div><div class="transmission-card" aria-live="polite"><span id="signalKicker">01 / PEOPLE, NOT RANKS</span><h2 id="signalTitle">Your people.<br>Your next squad.</h2><p id="signalText">Global Conflicts. Tactical Arma Reforger, built around teamwork.</p><a id="signalAction" href="#signal/join">Find your squad ↗</a></div><a class="connect-disc" href="#signal/join"><span>JOIN THE<br>COMMUNITY</span><b>↗</b></a><div class="signal-time"><span>WEEKEND FREQUENCY</span><strong>SAT / SUN<br>19:00 UTC</strong><small>Reference schedule<br>Confirm Reforger events with GC</small></div><a class="rewind-link" href="#signal/playback"><span>◀◀</span><div>THE MISSION DOESN’T END HERE.<br><b>Enter the playback lab ↗</b></div></a></section>`;
}
function globe(){return `<svg viewBox="0 0 600 600" aria-label="Illustrative connected globe" role="img"><defs><clipPath id="sphere"><circle cx="300" cy="300" r="236"/></clipPath><radialGradient id="sphereGlow"><stop stop-color="#5284ff" stop-opacity=".3"/><stop offset="1" stop-color="#081c6d" stop-opacity=".1"/></radialGradient><pattern id="dots" width="9" height="9" patternUnits="userSpaceOnUse"><circle cx="2" cy="2" r="1.2" fill="#e6f0ff"/></pattern></defs><circle cx="300" cy="300" r="236" fill="url(#sphereGlow)" stroke="#b5cbff" stroke-opacity=".55"/><g clip-path="url(#sphere)" fill="none" stroke="#a7c3ff" stroke-opacity=".25">${[65,130,195,236].map(r=>`<ellipse cx="300" cy="300" rx="${r}" ry="236"/>`).join('')}${[150,220,300,380,450].map(y=>`<ellipse cx="300" cy="${y}" rx="236" ry="${Math.max(18,80-Math.abs(300-y)/3)}"/>`).join('')}<path d="M50 300H550M300 50V550"/></g><g clip-path="url(#sphere)" fill="url(#dots)" stroke="#b2c9ff" stroke-opacity=".6" stroke-width=".5"><path d="M92 166L143 126L205 122L246 149L233 182L266 216L239 250L207 249L190 281L163 271L144 233L110 219Z"/><path d="M204 293L245 286L286 317L270 353L268 389L242 426L225 469L208 444L216 397L198 358L184 321Z"/><path d="M308 128L354 114L373 132L412 122L456 151L508 174L534 217L513 249L462 248L449 284L419 267L397 234L367 240L350 216L319 218L306 188L328 167Z"/><path d="M326 243L368 231L399 268L390 310L365 349L344 380L326 346L303 310L305 269Z"/><path d="M448 364L478 348L507 364L511 397L472 410L439 391Z"/></g><ellipse cx="300" cy="300" rx="290" ry="86" transform="rotate(-25 300 300)" fill="none" stroke="#f4ff90" stroke-width="1.5"/><circle cx="90" cy="440" r="5" fill="#f4ff90"/><circle cx="473" cy="135" r="4" fill="#f4ff90"/></svg>`}
function wireSignal(){const channels={who:['01 / PEOPLE, NOT RANKS','Your people.<br>Your next squad.','Global Conflicts. Tactical Arma Reforger, built around teamwork.','Find your squad ↗','join'],when:['02 / THE RENDEZVOUS','Same time.<br>Shared objective.','Saturday & Sunday, 19:00 UTC. Reference schedule; confirm Reforger events with GC.','Explore sessions ↗','operations'],how:['03 / OPEN CHANNEL','Mic on.<br>Come as you are.','Bring a working microphone and a mature attitude. Meet GC and confirm your server setup.','Get connected ↗','join']};document.querySelectorAll('[data-channel]').forEach(b=>b.onclick=()=>{const c=channels[b.dataset.channel];document.querySelector('#signalKicker').textContent=c[0];document.querySelector('#signalTitle').innerHTML=c[1];document.querySelector('#signalText').textContent=c[2];document.querySelector('#signalAction').textContent=c[3];document.querySelector('#signalAction').href='#signal/'+c[4];document.querySelectorAll('[data-channel]').forEach(el=>{el.classList.toggle('selected',el===b);el.setAttribute('aria-pressed',el===b?'true':'false')})})}
function operations(){const rows=['Saturday','Sunday'].map((day,i)=>`<article><span class="session-number">0${i+1}</span><div><span class="eyebrow">Weekly reference schedule</span><h2>${day}</h2></div><div class="session-time">19:00 <span>UTC</span></div>${link('join','Joining instructions ↗','text-link')}</article>`).join('');return `<div class="page-heading"><span class="eyebrow">${currentTheme==='field'?'Deployment schedule':currentTheme==='signal'?'02 / Rendezvous':'Sessions'}</span><h1>${currentTheme==='field'?'BE READY.<br>BE TOGETHER.':currentTheme==='signal'?'Meet on the<br>same frequency.':'Your weekend,<br>with the squad.'}</h1><p>GC’s published weekend schedule. Confirm Reforger-specific events with the community.</p></div><section class="schedule">${rows}</section><a class="btn" href="https://globalconflicts.net/" target="_blank" rel="noopener">Confirm with Global Conflicts ↗</a>`}
function join(){return `<div class="page-heading"><span class="eyebrow">${currentTheme==='field'?'Enlistment / no rank required':currentTheme==='signal'?'03 / Open a channel':'Get started'}</span><h1>${currentTheme==='field'?'YOUR PLACE<br>IN THE SQUAD.':currentTheme==='signal'?'You’re one<br>connection away.':'Come as you are.'}</h1><p>A working microphone. A mature attitude. A willingness to work together.</p></div><section class="steps"><article class="step"><b>01</b><div><h2>Meet the community.</h2><p>GC’s current site has the Discord link, guides, and latest community information.</p><a class="btn" href="https://globalconflicts.net/" target="_blank" rel="noopener">Open Global Conflicts ↗</a></div></article><article class="step"><b>02</b><div><h2>Get session-ready.</h2><p>Confirm the Reforger server, required mods, and event time with the community. Check your microphone.</p></div></article><article class="step"><b>03</b><div><h2>Find your squad.</h2><p>Follow the server instructions, listen to the briefing, and work with your team.</p>${link('operations','View the reference schedule →','text-link')}</div></article></section>`}
function playback(){return `<div class="page-heading player-heading"><div><span class="eyebrow">${currentTheme==='field'?'After action / briefing room':currentTheme==='signal'?'Rewind / transmission archive':'Briefing player'} · SIMULATED DATA</span><h1>${currentTheme==='field'?'OPERATION PINE':currentTheme==='signal'?'Rewind the operation.':'Operation Pine'}</h1></div><p>Fictional scenario · 2 min demo</p></div><section class="workspace" aria-label="Briefing player"><aside class="sidebar"><div class="eyebrow">Chapters</div><button data-time="0">01 &nbsp; Situation</button><button data-time="35">02 &nbsp; Approach</button><button data-time="70">03 &nbsp; Objective</button><button data-time="100">04 &nbsp; Debrief</button></aside><div class="map">${terrain()}<span class="map-caption">ILLUSTRATIVE TERRAIN / NOT GAME DATA</span></div><aside class="intel"><div><span class="eyebrow">Briefing notes</span><h3 id="chapterTitle">Situation</h3><p id="chapterNote"></p></div><div><span class="eyebrow">Map layers</span><label><input type="checkbox" checked id="units"> Squad positions</label><label><input type="checkbox" checked id="routes"> Planned route</label></div></aside></section><div class="timeline"><button id="play" aria-label="Play simulated briefing">▶ Play</button><output id="time">00:00 / 02:00</output><input aria-label="Playback position" id="scrub" type="range" min="0" max="120" value="0"><select id="speed" aria-label="Playback speed"><option value="1">1× speed</option><option value="2">2× speed</option><option value="4">4× speed</option></select><button id="reset">↺ Reset</button></div><p class="demo-note">Interactive concept with simulated data. Live recordings and game integration are future work.</p>`}
function wirePlayer(){position=0;const notes=['Alpha and Bravo assemble southwest of the objective. Review the planned approach.','Alpha advances along the marked route. Bravo holds the southern approach.','Alpha reaches the objective area. Coordinate the final approach with Bravo.','Review squad movement and timing. Use the timeline to revisit key moments.'];function update(){document.querySelector('#scrub').value=position;document.querySelector('#time').textContent=`${String(Math.floor(position/60)).padStart(2,'0')}:${String(Math.floor(position%60)).padStart(2,'0')} / 02:00`;let idx=position<35?0:position<70?1:position<100?2:3;document.querySelector('#chapterTitle').textContent=['Situation','Approach','Objective','Debrief'][idx];document.querySelector('#chapterNote').textContent=notes[idx];document.querySelectorAll('[data-time]').forEach((b,i)=>b.classList.toggle('selected',i===idx));document.querySelector('#squad').setAttribute('transform',`translate(${100+position*2.58} ${355-position*1.7})`)}function stop(){clearInterval(timer);timer=null;document.querySelector('#play').textContent='▶ Play';document.querySelector('#play').setAttribute('aria-label','Play simulated briefing')}document.querySelector('#play').onclick=()=>{if(timer){stop();return}if(position>=120)position=0;document.querySelector('#play').textContent='Ⅱ Pause';document.querySelector('#play').setAttribute('aria-label','Pause simulated briefing');timer=setInterval(()=>{position=Math.min(120,position+.25*Number(document.querySelector('#speed').value));update();if(position>=120)stop()},250)};document.querySelector('#scrub').oninput=e=>{position=Number(e.target.value);update()};document.querySelectorAll('[data-time]').forEach(b=>b.onclick=()=>{position=Number(b.dataset.time);update()});document.querySelector('#reset').onclick=()=>{stop();position=0;update()};document.querySelector('#units').onchange=e=>document.querySelector('#unitLayer').style.display=e.target.checked?'':'none';document.querySelector('#routes').onchange=e=>document.querySelector('#routeLayer').style.display=e.target.checked?'':'none';update()}
window.addEventListener('hashchange',render);render();

